  "a JPEG picture": "зображення JPEG",
  "a PNG picture": "зображення PNG",
  "a GIF picture": "зображення GIF",
  "a WebP picture": "зображення WebP",
  "a ZIP archive": "архів ZIP",
  "a PDF document": "документ PDF",
